@props([
    'variant' => 'outline',
    'size' => null,
    'color' => null,
    'type' => 'button',
    'href' => null,
    'as' => null,
    'square' => false,
    'loading' => null,
    'leading' => null,
    'trailing' => null,
])

@php
    use Illuminate\View\ComponentSlot;
    use App\Support\Stencil\Button\ButtonClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $interactionState = app(InteractionStateAttributes::class);

    $resolveAffix = static function (mixed $value): array {
        if ($value instanceof ComponentSlot) {
            return [! $value->isEmpty(), $value->isEmpty() ? null : $value];
        }

        if (filled($value)) {
            return [true, $value];
        }

        return [false, null];
    };

    [$hasLeading, $leadingContent] = $resolveAffix($leading ?? null);
    [$hasTrailing, $trailingContent] = $resolveAffix($trailing ?? null);

    $slotEmpty = $slot->isEmpty();
    $iconOnly = $slotEmpty && ($hasLeading || $hasTrailing || (bool) $square);

    $classMap = app(ButtonClassMap::class);

    $buttonClasses = $classMap->classes(
        $variant,
        $size,
        $color,
        [
            'hasLeading' => $hasLeading,
            'hasTrailing' => $hasTrailing,
            'square' => (bool) $square,
            'iconOnly' => $iconOnly,
        ],
    );

    $useLink = filled($href) || $as === 'a';
    $tag = $useLink ? 'a' : 'button';

    $mergedAttributes = $attributes
        ->except(['loading'])
        ->class($buttonClasses)
        ->merge([
            'data-button' => true,
        ]);

    $mergedAttributes = $interactionState->apply($mergedAttributes, [
        'nativeDisabled' => ! $useLink,
        'loading' => $loading === true ? true : null,
    ]);

    $isLoading = $interactionState->isLoading($mergedAttributes);

    if ($useLink) {
        $mergedAttributes = $mergedAttributes->merge([
            'href' => $href ?? '#',
        ]);
    } else {
        $mergedAttributes = $mergedAttributes->merge([
            'type' => $type,
        ]);
    }

    if ($iconOnly) {
        $mergedAttributes = $mergedAttributes->merge(['data-button-icon-only' => true]);
    }
@endphp

<{{ $tag }} {{ $mergedAttributes }}>
    @if ($hasLeading)
        <span @class(['button__leading', 'inline-flex shrink-0 items-center']) data-button-leading>
            @if ($leadingContent instanceof ComponentSlot)
                {{ $leadingContent }}
            @else
                {{ $leadingContent }}
            @endif
        </span>
    @endif

    @unless ($slotEmpty)
        <span @class(['button__label', 'inline-flex items-center']) data-button-label>
            {{ $slot }}
        </span>
    @endunless

    @if ($isLoading)
        <span @class(['button__loading', 'inline-flex shrink-0 items-center']) data-button-loading aria-hidden="true">
            @php
    $loadingVariant = \App\Support\Stencil\Icon\IconVariant::normalize($variant ?? 'outline');
    $loadingIconClasses = \App\Support\Stencil\Icon\IconVariant::classString($loadingVariant);
    $loadingStrokeWidth = \App\Support\Stencil\Icon\IconVariant::strokeWidth($loadingVariant);
    $loadingPixelSize = \App\Support\Stencil\Icon\IconVariant::pixelSize($loadingVariant);
    $loadingMergedClass = trim($loadingIconClasses.' animate-spin '.($class ?? ''));
@endphp

<svg
    class="{{ $loadingMergedClass }}"
    width="{{ $loadingPixelSize }}"
    height="{{ $loadingPixelSize }}"
    data-icon
    data-button-loading-icon
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="{{ $loadingStrokeWidth }}"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
>
    <path d="M21 12a9 9 0 1 1-6.219-8.56" />
</svg>

        </span>
    @elseif ($hasTrailing)
        <span @class(['button__trailing', 'inline-flex shrink-0 items-center']) data-button-trailing>
            @if ($trailingContent instanceof ComponentSlot)
                {{ $trailingContent }}
            @else
                {{ $trailingContent }}
            @endif
        </span>
    @endif
</{{ $tag }}>
